insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-comentario','q23','open','{}'::jsonb,1,0,'Es una paradoja: no tenían una utilidad práctica, pero al no estar ocupados dejaban la mente libre para pensar, observar y crear.','1 si explica la paradoja con palabras propias · 0,5 si es parcial · 0 si copia el texto. −0,1 por cada error de lengua.') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
