insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-comentario','eb','open','{}'::jsonb,4,0,'Respuesta libre. Ejemplo de estructura: tesis; argumento 1 (creatividad y juego autónomo); argumento 2 (tolerancia a la frustración); contraargumento (estímulos educativos) y respuesta; conclusión.','Adecuación 1 (al menos dos argumentos válidos y distintos, 0,5 cada uno, y responde a la pregunta) · Coherencia 1,5 · Estilo 1,5. Resta 0,1 por cada error de lengua al puntuarte.') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_defs(mock_id,course,title,duration_minutes,structure,content_version) values ('s1-economia','economia','Simulacro 1 · Economía de la Empresa',90,'{"sections":[{"id":"p1","label":"Ejercicios (elija 4 de 5)","choose":4,"groups":[{"id":"e1","points":2.5,"mode":"sum","floor0":false,"items":["e1a","e1b","e1c","e1d"]},{"id":"e2","points":2.5,"mode":"sum","floor0":false,"items":["e2a","e2b","e2c"]},{"id":"e3","points":2.5,"mode":"sum","floor0":false,"items":["e3a","e3b","e3c","e3d"]},{"id":"e4","points":2.5,"mode":"sum","floor0":false,"items":["e4a","e4b"]},{"id":"e5","points":2.5,"mode":"sum","floor0":true,"items":["t1","t2","t3","t4","t5","t6","t7","t8","t9","t10"]}]}],"word_rules":{}}'::jsonb,1) on conflict (mock_id) do update set course=excluded.course,title=excluded.title,duration_minutes=excluded.duration_minutes,structure=excluded.structure,content_version=excluded.content_version,updated_at=now();
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e1a','numeric','{"value":30000,"display":"30.000 €","tol_abs":1}'::jsonb,0.75,0,'$FM=AC-PC=(30.000+25.000+15.000)-40.000=30.000$ €.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e1b','numeric','{"value":1.75,"display":"1,75","tol_abs":0.01}'::jsonb,0.5,0,'$70.000/40.000=1{,}75$.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e1c','numeric','{"value":1,"display":"1,00","tol_abs":0.01}'::jsonb,0.5,0,'$(25.000+15.000)/40.000=1{,}00$.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e1d','open','{}'::jsonb,0.75,0,'El fondo de maniobra es positivo (30.000 €): los recursos permanentes financian todo el activo no corriente y parte del corriente, hay equilibrio financiero. La liquidez de 1,75 indica que el activo corriente cubre holgadamente las deudas a corto plazo. La tesorería de 1,00 muestra que, incluso sin vender existencias, la empresa puede atender sus pagos a corto plazo, aunque sin mucho margen.','0,25 por interpretar correctamente cada uno de los tres resultados (signo y significado del FM, liquidez > 1, tesorería ≈ 1). Sin interpretación o solo cifras: 0.') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e2a','numeric','{"value":3252.69,"display":"3.252,69 €","tol_abs":5}'::jsonb,1,0,'$VAN=-50.000+\dfrac{18.000}{1{,}06}+\dfrac{20.000}{1{,}06^2}+\dfrac{22.000}{1{,}06^3}=-50.000+16.981{,}13+17.799{,}93+18.471{,}63=3.252{,}69$ €.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e2b','numeric','{"value":2.55,"display":"2,55 años (≈ 2 años y 6,5 meses)","tol_abs":0.02}'::jsonb,0.75,0,'Acumulado: 18.000 (año 1), 38.000 (año 2). Faltan 12.000 de los 22.000 del año 3: $2+12.000/22.000=2{,}55$ años.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e2c','open','{}'::jsonb,0.75,0,'Sí: el VAN es positivo (3.252,69 €), así que el proyecto supera la rentabilidad exigida del 6 % y aporta valor. Además, la inversión se recupera en unos 2,55 años, antes del final de la vida del proyecto. Limitación del payback: no tiene en cuenta el valor del dinero en el tiempo ni los flujos posteriores a la recuperación.','0,25 decisión coherente con el VAN · 0,25 uso del payback como segundo criterio · 0,25 limitación correcta del payback.') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e3a','numeric','{"value":4000,"display":"4.000 unidades","tol_abs":0.5}'::jsonb,0.75,0,'$Q^*=\dfrac{CF}{p-cv}=\dfrac{40.000}{25-15}=4.000$ unidades.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e3b','numeric','{"value":15000,"display":"15.000 €","tol_abs":1}'::jsonb,0.75,0,'$B=(p-cv)\cdot Q-CF=10\cdot5.500-40.000=15.000$ €.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e3c','numeric','{"value":27.27,"display":"27,27 %","tol_abs":0.05}'::jsonb,0.5,0,'$(5.500-4.000)/5.500=0{,}2727=27{,}27$ %.','') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e3d','open','{}'::jsonb,0.5,0,'Subiría a 50.000/10 = 5.000 unidades: con los mismos precio y coste variable, hacen falta más ventas para cubrir unos costes fijos mayores, y el margen de seguridad con 5.500 unidades bajaría a 9,1 %.','0,25 por indicar que el punto muerto aumenta (con 5.000 u.) · 0,25 por razonarlo con el margen de contribución unitario.') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e4a','open','{}'::jsonb,1.25,0,'Responsabilidad: en ambas, limitada al capital aportado. Capital mínimo: la SA exige 60.000 €; la SL, una cantidad mucho menor (comprueba la normativa vigente). Transmisión: las acciones de la SA se transmiten libremente; las participaciones de la SL tienen restricciones (derecho de adquisición preferente de los socios).','0,4 por cada aspecto bien comparado (máx. 1,2) + 0,05 por presentación clara. Admitir cifras de capital de la SL según la normativa vigente.') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
insert into public.academy_mock_items(mock_id,item_id,kind,key,points,wrong_penalty,solution_md,rubric_md) values ('s1-economia','e4b','open','{}'::jsonb,1.25,0,'Ejemplo: Fortaleza: personal con experiencia en control de inventario. Debilidad: poca capacidad de financiación. Oportunidad: crecimiento del comercio electrónico en el Benelux. Amenaza: competencia de grandes operadores. Estrategia ofensiva (F+O): ofrecer servicio especializado de inventario a tiendas online belgas.','0,25 por cada cuadrante correcto (interno: F/D; externo: O/A) · 0,25 por una estrategia que combine dos elementos de forma coherente.') on conflict (mock_id,item_id) do update set kind=excluded.kind,key=excluded.key,points=excluded.points,wrong_penalty=excluded.wrong_penalty,solution_md=excluded.solution_md,rubric_md=excluded.rubric_md;
